import { describe, expect, it } from 'vitest'
import { exportRisFields, importRisFields } from '../src/citation-exchange.js'
import { LiteratureCitationFormatter } from '../src/index.js'
import { toCslItem } from '../src/csl.js'
import type { BibliographicRecord } from '../src/contracts.js'

// Fixed historical bytes, deliberately not generated by today's exporter.
const oldBook = `TY  - BOOK
TI  - Legacy institutions
A3  - Department, University
N1  - DRA literal creator: ["A3",0,"Department, University"]
A4  - Translation, Institute
N1  - DRA literal creator: ["A4",0,"Translation, Institute"]
ER  -
`
const oldArticle = `TY  - JOUR
TI  - Legacy article
A2  - Department, University
N1  - DRA literal creator: ["A2",0,"Department, University"]
A4  - Translation, Institute
N1  - DRA literal creator: ["A4",0,"Translation, Institute"]
ER  -
`

describe('RIS literal creator compatibility', () => {
  it.each([oldBook, oldArticle])(
    'imports historical institution names through the formatter',
    async (input) => {
      const result = await new LiteratureCitationFormatter().parseReferences(input)
      expect(result.errors).toEqual([])
      expect(result.items[0]?.creators).toEqual([
        { creatorType: 'editor', nameMode: 'organization', literalName: 'Department, University' },
        {
          creatorType: 'translator',
          nameMode: 'organization',
          literalName: 'Translation, Institute'
        }
      ])
    }
  )

  it.each(['book', 'article-journal'])('writes only new markers and round-trips %s', (type) => {
    const item = {
      id: 'x',
      title: 'Institutions',
      type,
      editor: [{ literal: 'Department, University' }],
      translator: [{ literal: 'Translation, Institute' }]
    }
    const text = exportRisFields(item)
    expect(text).toContain('Baselio literal creator: ')
    expect(text).not.toContain('DRA literal creator: ')
    expect(importRisFields(text, { type })).toMatchObject({
      editor: item.editor,
      translator: item.translator
    })
  })

  it.each(['Baselio literal creator: ', 'DRA literal creator: '])(
    'validates all %s markers against the visible tag, index and value',
    (prefix) => {
      for (const marker of [
        '{broken',
        '{}',
        '["A3",-1,"Department, University"]',
        '["A3",99,"Department, University"]',
        '["A3","0","Department, University"]',
        '["A4",0,"Department, University"]',
        '["A3",0,"Changed, Institution"]',
        '["A3",0,42]',
        '["A3",0,"Department, University","extra"]'
      ]) {
        const result = importRisFields(`A3  - Department, University\nN1  - ${prefix}${marker}\n`, {
          type: 'book'
        })
        expect(result.editor, marker).toEqual([{ family: 'Department', given: 'University' }])
      }
      const reordered = `A3  - Person, Ada\nA3  - Department, University\nN1  - ${prefix}["A3",0,"Department, University"]\n`
      expect(importRisFields(reordered, { type: 'book' }).editor).toEqual([
        { family: 'Person', given: 'Ada' },
        { family: 'Department', given: 'University' }
      ])
    }
  )

  it('ignores unknown notes and notes outside the record', () => {
    expect(
      importRisFields(
        'A3  - Department, University\nN1  - Unknown literal creator: ["A3",0,"Department, University"]\nER  -\nN1  - DRA literal creator: ["A3",0,"Department, University"]',
        { type: 'book' }
      ).editor
    ).toEqual([{ family: 'Department', given: 'University' }])
  })
})

// #152: the CSL conversion now puts a surname particle in its own field, so every consumer has to
// join it back. RIS writes editors (A3) and translators (A4) from that name, and reading `family`
// alone dropped the particle: "von Elm, Ada" became "Elm, Ada".
describe('RIS personal creators keep surname particles', () => {
  const particleItem = () => {
    const record: BibliographicRecord = {
      itemType: 'book',
      title: 'Edited volume',
      abstract: '',
      issuedText: '2007',
      issuedYear: 2007,
      containerTitle: '',
      shortTitle: '',
      language: 'en',
      rights: '',
      url: '',
      extra: '',
      typeFields: {},
      identifiers: [],
      creators: [
        { creatorType: 'editor', nameMode: 'person', givenName: 'Ada', familyName: 'von Elm' },
        { creatorType: 'translator', nameMode: 'person', givenName: 'Ada', familyName: 'von Elm' }
      ]
    }
    return toCslItem('particle', record)
  }

  it('writes the editor particle on the A3 line', () => {
    const item = particleItem()
    expect(item.editor).toEqual([{ family: 'Elm', given: 'Ada', 'non-dropping-particle': 'von' }])
    const lines = exportRisFields(item, 'book').split('\n')
    expect(lines).toContain('A3  - von Elm, Ada')
    // The regression wrote the half surname on its own line.
    expect(lines).not.toContain('A3  - Elm, Ada')
  })

  it('writes the translator particle on the A4 line', () => {
    const lines = exportRisFields(particleItem(), 'book').split('\n')
    expect(lines).toContain('A4  - von Elm, Ada')
    expect(lines).not.toContain('A4  - Elm, Ada')
  })

  it('round-trips a particle editor and translator through RIS', () => {
    const text = exportRisFields(particleItem(), 'book')
    const reimported = importRisFields(text, { type: 'book' })
    // Rows share one RIS name shape, so the joining rule is the assertion: no half surname.
    expect(reimported.editor).toEqual([{ family: 'von Elm', given: 'Ada' }])
    expect(reimported.translator).toEqual([{ family: 'von Elm', given: 'Ada' }])
    expect(text.split('\n').filter((line) => /^A[34] {2}- Elm, /u.test(line))).toEqual([])
  })
})
